    {
      "rel": "related",
      "href": "https://ows.emodnet-humanactivities.eu/wfs?service=WFS&version=2.0.0&request=DescribeFeatureType&typeNames=emodnet:nationallydesignatedareas",
      "title": "EMODnet Human Activities: nationallydesignatedareas"
